languages.csharp:
if (text.Length == 0) return text;
var first = text.EnumerateRunes().First();
return first.ToString().ToUpperInvariant() + text.Substring(first.Utf16SequenceLength);

languages.rust:
if text.is_empty() { return text; }
let mut chars = text.chars();
let first = chars.next().unwrap();
return first.to_uppercase().collect::<String>() + chars.as_str();

languages.java:
if (text.isEmpty()) return text;
int size = Character.charCount(text.codePointAt(0));
return text.substring(0, size).toUpperCase(java.util.Locale.ROOT) + text.substring(size);

languages.go:
if text == "" {
	return text
}
chars := []rune(text)
return strings.ToUpper(string(chars[0])) + string(chars[1:])
